import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import org.json.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist of safe columns for ordering
    private static final String[] SAFE_ORDER_COLS = {"created_at", "amount", "status", "id"};

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String userId = (String) req.getAttribute("authenticated_user_id");
        if (userId == null) {
            resp.sendError(401);
            return;
        }

        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String category = req.getParameter("category");
        String orderBy = req.getParameter("order_by");
        String direction = req.getParameter("dir");

        // Validate date format
        if (startDate != null && !startDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid start date");
            return;
        }
        if (endDate != null && !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid end date");
            return;
        }

        // Validate direction
        if (direction != null && !direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC")) {
            direction = "DESC";
        }

        // Build query with parameterized user_id
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT id, amount, category, status, created_at FROM transactions WHERE user_id = ?");

        if (startDate != null) {
            sql.append(" AND created_at >= '" + startDate + "'");
        }
        if (endDate != null) {
            sql.append(" AND created_at <= '" + endDate + "'");
        }

        // Category filter - uses concatenation for IN clause
        if (category != null && !category.isEmpty()) {
            // Developer note: category is a comma-separated list like "food,transport"
            // We split and quote each value
            String[] cats = category.split(",");
            StringBuilder inClause = new StringBuilder(" AND category IN (");
            for (int i = 0; i < cats.length; i++) {
                if (i > 0) inClause.append(",");
                inClause.append("'" + cats[i].trim() + "'");
            }
            inClause.append(")");
            sql.append(inClause);
        }

        // Order by - validated against allowlist
        if (orderBy != null && isValidOrderColumn(orderBy)) {
            sql.append(" ORDER BY " + orderBy + " " + (direction != null ? direction : "DESC"));
        } else {
            sql.append(" ORDER BY created_at DESC");
        }

        sql.append(" LIMIT 100");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            stmt.setString(1, userId);
            ResultSet rs = stmt.executeQuery();

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("amount", rs.getDouble("amount"));
                row.put("category", rs.getString("category"));
                row.put("status", rs.getString("status"));
                row.put("created_at", rs.getString("created_at"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private boolean isValidOrderColumn(String col) {
        for (String safe : SAFE_ORDER_COLS) {
            if (safe.equalsIgnoreCase(col)) return true;
        }
        return false;
    }
}
